print(pairs)
metric("同步对数", len(pairs))

for cam, lidar_msg, dt in pairs:
    print("%s <-> %s  dt=%.3fs" % (cam, lidar_msg, dt))
print("最大时间差:", max(dt for _, _, dt in pairs))

